#[cfg(test)]
fn replace_complete_projection<T, E>(target: &mut T, projection: Result<T, E>) -> Result<(), E> {
    match projection {
        Ok(value) => {
            *target = value;
            Ok(())
        }
        Err(error) => Err(error),
    }
}

fn retained_string_bytes(value: &String) -> usize {
    value.capacity()
}

fn retained_string_vec_bytes(values: &[String], capacity: usize) -> Option<usize> {
    std::mem::size_of::<String>()
        .checked_mul(capacity)?
        .checked_add(
            values
                .iter()
                .try_fold(0usize, |total, value| total.checked_add(value.capacity()))?,
        )
}

fn retained_agent_session_row_bytes(row: &storage::AgentSessionRow) -> Option<usize> {
    std::mem::size_of::<storage::AgentSessionRow>()
        .checked_add(row.pane_id.capacity())?
        .checked_add(row.kind.capacity())?
        .checked_add(row.session_id.capacity())
}

fn retained_binding_reconcile_bytes(
    value: &storage::AgentSessionBindingReconcile,
) -> Option<usize> {
    std::mem::size_of::<storage::AgentSessionBindingReconcile>()
        .checked_add(retained_string_vec_bytes(
            &value.live_pane_ids,
            value.live_pane_ids.capacity(),
        )?)?
        .checked_add(
            std::mem::size_of::<storage::AgentSessionRow>()
                .checked_mul(value.desired_bindings.capacity())?,
        )?
        .checked_add(
            value
                .desired_bindings
                .iter()
                .try_fold(0usize, |total, row| {
                    total.checked_add(
                        retained_agent_session_row_bytes(row)?
                            .saturating_sub(std::mem::size_of::<storage::AgentSessionRow>()),
                    )
                })?,
        )
}

fn retained_structured_mutations_bytes(
    values: &Vec<storage::StructuredThreadMutation>,
) -> Option<usize> {
    let mut total =
        std::mem::size_of::<storage::StructuredThreadMutation>().checked_mul(values.capacity())?;
    for value in values {
        let bytes = match value {
            storage::StructuredThreadMutation::Upsert(row) => [
                &row.local_session_id,
                &row.workspace_id,
                &row.thread_id,
                &row.title,
                &row.cwd,
            ]
            .into_iter()
            .try_fold(0usize, |sum, value| {
                sum.checked_add(retained_string_bytes(value))
            })?
            .checked_add(row.model.as_ref().map_or(0, String::capacity))?,
            storage::StructuredThreadMutation::SetArchived {
                local_session_id, ..
            }
            | storage::StructuredThreadMutation::Delete { local_session_id } => {
                retained_string_bytes(local_session_id)
            }
        };
        total = total.checked_add(bytes)?;
    }
    Some(total)
}

fn retained_work_history_mutations_bytes(
    values: &Vec<storage::AgentWorkHistoryMutation>,
) -> Option<usize> {
    let mut total =
        std::mem::size_of::<storage::AgentWorkHistoryMutation>().checked_mul(values.capacity())?;
    for value in values {
        let storage::AgentWorkHistoryMutation::Upsert(row) = value;
        total = total
            .checked_add(row.workspace_id.capacity())?
            .checked_add(row.pane_id.capacity())?
            .checked_add(row.kind.capacity())?
            .checked_add(row.agent_session_id.capacity())?
            .checked_add(row.turn_key.capacity())?
            .checked_add(row.instruction.capacity())?
            .checked_add(row.agent_summary.as_ref().map_or(0, String::capacity))?
            .checked_add(row.model.as_ref().map_or(0, String::capacity))?
            .checked_add(row.effort.as_ref().map_or(0, String::capacity))?
            .checked_add(row.cwd.as_ref().map_or(0, String::capacity))?
            .checked_add(row.branch.as_ref().map_or(0, String::capacity))?;
    }
    Some(total)
}

fn work_history_key(row: &storage::AgentWorkTurnUpsert) -> (String, String, String) {
    (
        row.kind.clone(),
        row.agent_session_id.clone(),
        row.turn_key.clone(),
    )
}

fn same_work_history_projection(
    left: &storage::AgentWorkTurnUpsert,
    right: &storage::AgentWorkTurnUpsert,
) -> bool {
    let mut left = left.clone();
    let mut right = right.clone();
    left.updated_at = 0;
    right.updated_at = 0;
    left == right
}

type DetectedWorkHistoryFacts = (Option<String>, Option<String>, Option<u32>);

fn detected_work_history_facts(
    previous: Option<DetectedWorkHistoryFacts>,
    first_observed_cwd: Option<&str>,
) -> DetectedWorkHistoryFacts {
    previous.unwrap_or_else(|| (first_observed_cwd.map(str::to_owned), None, None))
}

/// leaf(`ui::work_history`)는 storage 크레이트를 참조할 수 없으므로, durable
/// work-turn row → leaf 뷰모델 변환은 App이 담당한다. 렌더 직전에 호출해 빌린
/// 뷰만 만든다 — 여기서 문자열을 복제하지 않는다.
impl From<storage::AgentWorkTurnState> for ui::work_history::WorkHistoryState {
    fn from(state: storage::AgentWorkTurnState) -> Self {
        match state {
            storage::AgentWorkTurnState::Working => Self::Working,
            storage::AgentWorkTurnState::Waiting => Self::Waiting,
            storage::AgentWorkTurnState::Completed => Self::Completed,
        }
    }
}

impl<'a> From<&'a storage::AgentWorkTurnRow> for ui::work_history::WorkHistoryRow<'a> {
    fn from(row: &'a storage::AgentWorkTurnRow) -> Self {
        Self {
            workspace_id: &row.workspace_id,
            kind: &row.kind,
            agent_session_id: &row.agent_session_id,
            turn_key: &row.turn_key,
            source_offset: row.source_offset,
            instruction: &row.instruction,
            agent_summary: row.agent_summary.as_deref(),
            messages_json: row.messages_json.as_deref(),
            model: row.model.as_deref(),
            effort: row.effort.as_deref(),
            branch: row.branch.as_deref(),
            git_change_count: row.git_change_count,
            state: row.state.into(),
            updated_at: row.updated_at,
        }
    }
}

/// durable identity는 프레임을 넘어 살아남아야 하는 owned 값이라(action, 카드
/// 펼침 선택 등) 빌린 뷰와 별개로 storage row에서 직접 만든다.
impl From<&storage::AgentWorkTurnRow> for ui::work_history::WorkTurnIdentity {
    fn from(row: &storage::AgentWorkTurnRow) -> Self {
        Self {
            workspace_id: row.workspace_id.clone(),
            kind: row.kind.clone(),
            agent_session_id: row.agent_session_id.clone(),
            turn_key: row.turn_key.clone(),
        }
    }
}

