// 기존 controller 요청(특히 현재 workspace의 dotenv 동기화)을 덮어쓰거나 앞지르지 않는다.
fn retry_workspace_session_open(
    slot: &mut Option<WorkspaceControllerAction>,
    pending: &mut Option<String>,
) -> bool {
    if slot.is_some() {
        return false;
    }
    let Some(workspace_id) = pending.take() else {
        return false;
    };
    *slot = Some(WorkspaceControllerAction::OpenAgentLauncherForWorkspace(
        workspace_id,
    ));
    true
}

fn queue_workspace_session_open(
    slot: &mut Option<WorkspaceControllerAction>,
    pending: &mut Option<String>,
    workspace_id: String,
) -> bool {
    // 아직 입장하지 못한 창 열기는 최신 대상 하나로 병합한다. 세션 생성은 하지 않는다.
    *pending = Some(workspace_id);
    retry_workspace_session_open(slot, pending)
}

#[derive(Debug, PartialEq, Eq)]
enum WorkspaceSessionOpenStep {
    Reject,
    Switch,
    Open,
}

fn workspace_session_open_step(
    target_id: &str,
    active_id: &str,
    target_exists: bool,
    launcher_busy: bool,
) -> WorkspaceSessionOpenStep {
    if !target_exists || launcher_busy {
        WorkspaceSessionOpenStep::Reject
    } else if target_id == active_id {
        WorkspaceSessionOpenStep::Open
    } else {
        WorkspaceSessionOpenStep::Switch
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum ResourceMaintenanceAction {
    InspectUnattached,
    KillUnattached,
    KillSession(runtime::SessionId),
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct ResourceMaintenanceTarget {
    workspace_id: String,
    runtime_instance: u64,
    action: ResourceMaintenanceAction,
}

fn resource_target_matches_runtime(
    target: &ResourceMaintenanceTarget,
    workspace_id: &str,
    runtime_instance: u64,
) -> bool {
    target.workspace_id == workspace_id && target.runtime_instance == runtime_instance
}

fn workspace_focus_target_matches_runtime(
    target_workspace_id: &str,
    target_runtime_instance: Option<u64>,
    runtime_workspace_id: &str,
    runtime_instance: u64,
) -> bool {
    target_workspace_id == runtime_workspace_id
        && target_runtime_instance.is_none_or(|expected| expected == runtime_instance)
}

fn should_stage_catalog_restore(
    has_panes: bool,
    restore_lifecycle: WorkspaceRestoreLifecycle,
) -> bool {
    has_panes && restore_lifecycle == WorkspaceRestoreLifecycle::Idle
}

fn should_stage_primary_pane_activation(
    materialized: bool,
    restore_lifecycle: WorkspaceRestoreLifecycle,
) -> bool {
    !materialized && restore_lifecycle != WorkspaceRestoreLifecycle::AwaitingDelivery
}

fn should_restore_active_workspace(
    closed: bool,
    has_panes: bool,
    restore_lifecycle: WorkspaceRestoreLifecycle,
) -> bool {
    !closed && should_stage_catalog_restore(has_panes, restore_lifecycle)
}

fn warm_runtime_needs_restore(
    has_persisted_panes: bool,
    restore_lifecycle: WorkspaceRestoreLifecycle,
) -> bool {
    has_persisted_panes && restore_lifecycle == WorkspaceRestoreLifecycle::Idle
}

fn restore_lifecycle_after_dotenv_delivery(
    primary_activation: bool,
    full_restore: bool,
    delivered: bool,
) -> WorkspaceRestoreLifecycle {
    if !delivered {
        WorkspaceRestoreLifecycle::Idle
    } else if full_restore {
        WorkspaceRestoreLifecycle::Delivered
    } else if primary_activation {
        WorkspaceRestoreLifecycle::AwaitingDelivery
    } else {
        WorkspaceRestoreLifecycle::Idle
    }
}

fn persisted_pane_is_current(
    rows: &[storage::PersistedActivityPane],
    pane: &runtime::MuxPaneId,
) -> bool {
    rows.iter().any(|row| row.pane_id == pane.0)
}

fn extend_unique_pane_ids<'a>(
    panes: &mut Vec<runtime::MuxPaneId>,
    persisted_panes: impl IntoIterator<Item = &'a str>,
) {
    for pane_id in persisted_panes {
        let pane = runtime::MuxPaneId(pane_id.to_owned());
        if !panes.contains(&pane) {
            panes.push(pane);
        }
    }
}

fn cancel_pending_focus_intents(
    pending_session: &mut Option<(String, u64, runtime::SessionId)>,
    pending_pane: &mut Option<PendingPaneFocus>,
) {
    *pending_session = None;
    *pending_pane = None;
}

fn live_pane_target_is_current(
    mux: &runtime::MuxSnapshot,
    tab: &runtime::MuxTabId,
    pane: &runtime::MuxPaneId,
) -> bool {
    mux.tabs.iter().any(|candidate| {
        candidate.id == *tab
            && candidate
                .panes
                .iter()
                .any(|candidate| candidate.id == *pane && candidate.session_id.is_some())
    })
}

fn invalidate_resource_projection(
    activity_rows_cache: &mut Option<(std::time::Instant, ui::activity::ActivitySnapshot)>,
) {
    *activity_rows_cache = None;
}

fn stage_resource_maintenance(
    queue: &mut std::collections::VecDeque<ResourceMaintenanceTarget>,
    target: ResourceMaintenanceTarget,
) -> bool {
    if let Some(existing) = queue
        .iter_mut()
        .find(|existing| existing.workspace_id == target.workspace_id)
    {
        *existing = target;
        return true;
    }
    if queue.len() >= ui::activity::MAX_ACTIVITY_WORKSPACES {
        return false;
    }
    queue.push_back(target);
    true
}

fn apply_unattached_events(
    counts: &mut std::collections::HashMap<String, u16>,
    workspace_id: &str,
    events: &[runtime::RuntimeEvent],
) -> bool {
    let mut updated = None;
    for event in events {
        match event {
            runtime::RuntimeEvent::UnattachedSessionsInspected { count } => {
                updated = Some(*count);
            }
            runtime::RuntimeEvent::UnattachedSessionsKilled { .. } => {
                updated = Some(0);
            }
            _ => {}
        }
    }
    let Some(count) = updated else {
        return false;
    };
    if counts.contains_key(workspace_id) || counts.len() < ui::activity::MAX_ACTIVITY_WORKSPACES {
        counts.insert(workspace_id.to_owned(), count);
        true
    } else {
        false
    }
}

fn prune_resource_tracking(
    counts: &mut std::collections::HashMap<String, u16>,
    queue: &mut std::collections::VecDeque<ResourceMaintenanceTarget>,
    mut retain: impl FnMut(&str) -> bool,
) {
    counts.retain(|workspace_id, _| retain(workspace_id));
    queue.retain(|target| retain(&target.workspace_id));
}

fn next_port_generation(generation: &mut u64) -> u64 {
    *generation = generation.wrapping_add(1).max(1);
    *generation
}

fn next_port_scan_job(
    generation: &mut u64,
    roots: Arc<[crate::port_inventory::PortWorkspaceRoot]>,
) -> crate::port_inventory::PortJob {
    crate::port_inventory::PortJob::Scan {
        generation: next_port_generation(generation),
        roots,
    }
}

fn next_port_termination_job(
    generation: &mut u64,
    roots: Arc<[crate::port_inventory::PortWorkspaceRoot]>,
    target: crate::port_inventory::PortTerminationTarget,
) -> crate::port_inventory::PortJob {
    crate::port_inventory::PortJob::Terminate {
        generation: next_port_generation(generation),
        roots,
        target,
    }
}

fn port_job_generation(job: &crate::port_inventory::PortJob) -> u64 {
    match job {
        crate::port_inventory::PortJob::Scan { generation, .. }
        | crate::port_inventory::PortJob::Terminate { generation, .. } => *generation,
    }
}

fn stage_pending_port_job(
    pending: &mut Option<crate::port_inventory::PortJob>,
    job: crate::port_inventory::PortJob,
) {
    *pending = Some(job);
}

fn prepare_port_job_submission(
    pending: &mut Option<crate::port_inventory::PortJob>,
    snapshot: &mut Option<crate::port_inventory::PortSnapshot>,
    current_generation: u64,
    job_generation: u64,
    explicit: bool,
) -> bool {
    if explicit {
        *pending = None;
        *snapshot = None;
    }
    job_generation == current_generation
}

fn stage_status_bar_intent(
    pending: &mut Option<ui::agent_terminal::StatusBarIntent>,
    intent: Option<ui::agent_terminal::StatusBarIntent>,
) -> bool {
    let Some(intent) = intent else {
        return false;
    };
    *pending = Some(intent);
    true
}

fn apply_port_outcome_if_current(
    cached: &mut Option<crate::port_inventory::PortSnapshot>,
    current_generation: u64,
    outcome: crate::port_inventory::PortOutcome,
) -> bool {
    let result = match outcome {
        crate::port_inventory::PortOutcome::Scanned(result)
        | crate::port_inventory::PortOutcome::Terminated(result) => result,
    };
    let Ok(snapshot) = result else {
        return false;
    };
    if snapshot.generation != current_generation {
        return false;
    }
    *cached = Some(snapshot);
    true
}

