    /// 신선도 계약 표. 창이 통째로 굴러가 지금과 겹치지 않게 된 슬롯만 비운다.
    #[test]
    fn 사용량_수치는_창이_통째로_굴러간_뒤에야_슬롯별로_버려진다() {
        let both = (Some(11), Some(77));
        let cases: &[(&str, f64, ProviderUsage)] = &[
            ("방금 기록", 0.0, (Some(11), Some(77))),
            (
                "2시간 — 5시간 창 안이라 둘 다 산다",
                120.0,
                (Some(11), Some(77)),
            ),
            ("5시간 정각 — 경계는 유효", 300.0, (Some(11), Some(77))),
            ("5시간 경과 — 5시간만 버린다", 301.0, (None, Some(77))),
            ("하루 — 주간은 여전히 유효", 1440.0, (None, Some(77))),
            ("7일 정각 — 경계는 유효", 10_080.0, (None, Some(77))),
            ("7일 경과 — 둘 다 버린다", 10_081.0, (None, None)),
            ("시계 되감김은 낡음이 아니다", -60.0, (Some(11), Some(77))),
        ];
        for (name, age_minutes, expected) in cases {
            assert_eq!(fresh_usage_windows(both, *age_minutes), *expected, "{name}");
        }
    }

    /// 없는 값은 신선해도 생기지 않는다 — 필터는 있는 슬롯만 건드린다.
    #[test]
    fn 신선도_필터는_비어있는_슬롯을_채우지_않는다() {
        assert_eq!(fresh_usage_windows((None, Some(77)), 0.0), (None, Some(77)));
        assert_eq!(fresh_usage_windows((Some(11), None), 0.0), (Some(11), None));
        assert_eq!(fresh_usage_windows((None, None), 0.0), (None, None));
    }

    /// 프로브 캐시도 같은 규칙을 쓰고, 두 창이 다 만료되면 "값 없음"으로 접힌다.
    #[test]
    fn 프로브_값은_두_창이_모두_만료되면_사라진다() {
        use std::time::Duration;

        let usage = (Some(11), Some(77));
        assert_eq!(
            fresh_usage_after(usage, Duration::from_secs(60)),
            Some((Some(11), Some(77)))
        );
        assert_eq!(
            fresh_usage_after(usage, Duration::from_secs(6 * 60 * 60)),
            Some((None, Some(77))),
            "5시간 창만 굴러갔으면 주간을 들고 남아야 한다"
        );
        assert_eq!(
            fresh_usage_after(usage, Duration::from_secs(8 * 24 * 60 * 60)),
            None,
            "둘 다 만료되면 None이라야 PTY 프로브 폴백이 살아난다"
        );
    }

    /// 낙관값에 시한이 없으면 CLI가 거절했을 때 거짓값이 영영 남고, 그 뒤 모든 누름이
    /// **실재하지 않는 값에서** 한 칸 움직인다 — 사용자에겐 몇 번을 눌러도 아무 일이
    /// 없는 것으로 보인다(2026-08-09: Claude Code 2.1.226이 조직 한도·런치 핀으로
    /// `/effort`를 거절하면서 실제로 이 상태가 됐다).
    ///
    /// 반대로 **아직 안 보낸 예약분까지 시한을 세면** 긴 턴을 기다리던 예약이 통째로
    /// 증발한다. 두 쪽이 다 필요해서 표로 고정한다.
    #[test]
    fn 낙관값은_확인되면_버리고_시한이_지나면_되돌린다() {
        use std::time::Duration;

        let over = PTY_PENDING_CONFIRM_TIMEOUT;
        let under = PTY_PENDING_CONFIRM_TIMEOUT - Duration::from_secs(1);
        // (권위값이 따라잡음, 아직 큐에 있음, 기다린 시간, 기대, 이유)
        let cases = [
            (
                true,
                false,
                Duration::ZERO,
                PendingVerdict::CaughtUp,
                "권위값이 따라잡으면 즉시 버린다",
            ),
            (
                true,
                true,
                over,
                PendingVerdict::CaughtUp,
                "따라잡았으면 큐에 있든 시한이 지났든 버린다",
            ),
            (
                false,
                false,
                under,
                PendingVerdict::Trust,
                "시한 전에는 방금 보낸 값을 믿는다 — 안 그러면 연속 누름이 같은 명령을 반복한다",
            ),
            (
                false,
                false,
                over,
                PendingVerdict::Unconfirmed,
                "보냈는데 시한이 지나도록 확인 안 되면 되돌린다",
            ),
            (
                false,
                true,
                over,
                PendingVerdict::Trust,
                "아직 안 보낸 예약분은 시한을 세지 않는다 — 긴 턴을 기다리는 중일 뿐이다",
            ),
        ];
        for (caught_up, queued, waited, expected, why) in cases {
            assert_eq!(
                pending_verdict(caught_up, queued, waited),
                expected,
                "{why}"
            );
        }
    }

    /// 자동 포트 스캔은 **토폴로지당 한 번**이어야 한다. 스캔이 실패하면
    /// `port_snapshot`은 None으로 남으므로, 래치 없이 "스냅샷이 없으면 건다"로 쓰면
    /// 매 프레임 lsof를 띄운다. 반대로 래치가 영영 안 풀리면 워크스페이스를 바꿔도
    /// 칩이 옛 토폴로지의 값에 머문다. 두 쪽이 다 필요해 소스로 고정한다.
    #[test]
    fn 자동_포트_스캔은_토폴로지당_한번이고_무효화때_다시_풀린다() {
        let source = include_str!("app.rs");
        let auto = source
            .split_once("    fn auto_scan_ports_once(&mut self) {")
            .and_then(|(_, tail)| tail.split_once("    fn request_port_scan("))
            .map(|(body, _)| body)
            .expect("auto_scan_ports_once 본문을 찾지 못했다");
        assert!(
            auto.contains("if self.port_auto_scan_done || self.port_snapshot.is_some() {"),
            "래치와 스냅샷을 둘 다 보지 않으면 실패한 스캔이 매 프레임 재시도된다"
        );
        assert!(
            auto.contains("self.port_auto_scan_done = true;"),
            "래치를 세우지 않으면 무한 재시도가 된다"
        );
        assert!(
            auto.contains("self.submit_port_job(job, false);"),
            "자동 스캔은 명시적 요청이 아니다 — explicit=true면 진행 중인 사용자 요청을 밀어낸다"
        );

        let invalidate = source
            .split_once("    fn invalidate_port_inventory_topology(&mut self) {")
            .and_then(|(_, tail)| tail.split_once("    fn poll_port_inventory("))
            .map(|(body, _)| body)
            .expect("invalidate_port_inventory_topology 본문을 찾지 못했다");
        assert!(
            invalidate.contains("self.port_auto_scan_done = false;"),
            "토폴로지가 바뀌었는데 래치가 남으면 칩이 옛 구성의 값에 머문다"
        );
    }

    /// 슬래시 명령은 **본문과 submit CR이 따로** 나가야 한다. 한 덩어리로 보내면
    /// CLI의 paste-burst 휴리스틱이 뒤따르는 CR을 붙여넣기 일부로 보고 삼켜, 명령이
    /// 입력줄에 남는다 — 사용자가 키를 한 번 더 눌러야 실행됐다(2026-08-09 실증).
    /// `composer.rs`가 같은 이유로 못박은 규칙인데 강도·모델 경로만 밖에 있었다.
    /// 메모 저장에서 **순서가 곧 데이터 보존**이다. 세 지점이 지켜져야 한다.
    ///
    /// 1. 워크스페이스 전환 시 **읽기 전에 flush** — 반대로 하면 이전 워크스페이스의
    ///    마지막 타건이 캐시 교체에 덮여 사라진다.
    /// 2. 타건이 멎으면 디바운스 만료를 **스스로 깨워야** 한다. egui는 입력이 없으면
    ///    프레임을 안 돌리므로 `request_repaint_after` 없이는 마지막 문장이 영영
    ///    저장되지 않는다.
    /// 3. 종료 시 flush — 종료가 디바운스보다 빠르면 통째로 잃는다.
    ///
    /// 셋 다 "실패해도 화면에 아무 일도 안 일어나는" 종류라 소스로 고정한다.
    #[test]
    fn 메모_자동저장은_읽기전_flush와_깨우기와_종료flush를_지킨다() {
        let source = include_str!("app.rs");

        let sync = source
            .split_once("    fn sync_workspace_note(&mut self, active_workspace_id: &str) {")
            .and_then(|(_, tail)| tail.split_once("\n    fn "))
            .map(|(body, _)| body)
            .expect("sync_workspace_note 본문을 찾지 못했다");
        let flush_at = sync
            .find("self.flush_pending_note();")
            .expect("전환 시 flush가 없다 — 이전 워크스페이스의 마지막 타건을 잃는다");
        let load_at = sync
            .find("self.db.load_workspace_note(")
            .expect("새 워크스페이스 메모를 읽지 않는다");
        assert!(
            flush_at < load_at,
            "flush가 load보다 뒤에 있다 — 캐시 교체가 미저장 편집을 덮는다"
        );

        let logic = source
            .split_once(
                "    fn logic(&mut self, ctx: &egui::Context, _frame: &mut eframe::Frame) {",
            )
            .and_then(|(_, tail)| tail.split_once("mem_pressure_monitor"))
            .map(|(body, _)| body)
            .expect("logic() 서두를 찾지 못했다");
        assert!(
            logic.contains("request_repaint_after(Self::NOTE_SAVE_DEBOUNCE - elapsed)"),
            "디바운스 만료를 깨우지 않으면 타건이 멎은 뒤 마지막 문장이 저장되지 않는다"
        );
        assert!(
            logic.contains("if self.pending_note.is_some()"),
            "밀린 편집이 없을 때도 타이머를 걸면 유휴 프레임을 만든다"
        );

        let shutdown = source
            .split_once("    fn shutdown_on_exit(&mut self) {")
            .and_then(|(_, tail)| tail.split_once("self.cancel_all_cross_workspace_restores();"))
            .map(|(body, _)| body)
            .expect("shutdown_on_exit 본문을 찾지 못했다");
        assert!(
            shutdown.contains("self.flush_pending_note();"),
            "종료 시 flush가 없으면 디바운스 대기 중이던 메모를 잃는다"
        );
    }

    #[test]
    fn 슬래시_명령은_본문과_cr을_나눠_보낸다() {
        let source = include_str!("app.rs");
        let body = source
            .split_once("    fn encode_slash_writes(")
            .and_then(|(_, tail)| tail.split_once("    /// 계획된 입력을 대상 PTY에"))
            .map(|(body, _)| body)
            .expect("encode_slash_writes 본문을 찾지 못했다");
        assert!(
            body.contains("plan_composer_input(line, false, bracketed, provider)"),
            "submit=true로 받으면 인코더가 CR을 본문에 붙여 한 덩어리가 된다"
        );
        assert!(
            body.contains(r#"vec![body, b"\r".to_vec()]"#),
            "CR이 별도 write로 나가지 않으면 paste-burst 휴리스틱에 삼켜진다"
        );

        // 계획 자체에도 CR이 남아 있으면 안 된다 — 그러면 CR이 두 번 나간다.
        let effort = include_str!("pty_effort.rs");
        assert!(
            !effort.contains(r#"format!("/effort {level}\r")"#)
                && !effort.contains(r#"format!("/model {level}\r")"#),
            "EffortPlan::Slash의 line에 CR이 남아 있으면 호출부의 분리가 무의미하다"
        );
    }

    /// `agent_info`는 transcript 바인딩에서만 만들어진다. 파서가 없는 에이전트(Kimi)는
    /// 프로세스가 감지돼도 카드에 줄이 없고, `agent_line.is_none()` 때문에 유휴가
    /// Off(회색)로 강등돼 평범한 셸과 구분되지 않는다 — 2026-08-09 실제 신고.
    /// 프로세스 감지로 빈칸을 채우되 **transcript 값은 덮지 않는다**.
    #[test]
    fn 프로세스로만_감지된_에이전트도_표시_항목을_얻는다() {
        use crate::agent_detect::{AgentDisplay, AgentKind, RunningAgent};
        use std::collections::HashMap;

        let rich = runtime::SessionId(1);
        let detected_only = runtime::SessionId(2);
        let mut info = HashMap::from([(
            rich,
            AgentDisplay {
                kind: AgentKind::Claude,
                model: Some("opus".to_owned()),
                effort: Some("xhigh".to_owned()),
                context_pct: Some(42),
                last_agent_summary: None,
                user_instruction: None,
            },
        )]);
        let kinds = HashMap::from([
            (
                rich,
                RunningAgent {
                    kind: AgentKind::Claude,
                    model: Some("argv-값".to_owned()),
                    effort: None,
                },
            ),
            (
                detected_only,
                RunningAgent {
                    kind: AgentKind::Kimi,
                    model: Some("kimi-code/k3".to_owned()),
                    effort: Some("high".to_owned()),
                },
            ),
        ]);

        merge_detected_kinds(&mut info, &kinds, &HashMap::new());

        let added = info.get(&detected_only).expect("빈칸이 채워져야 한다");
        assert_eq!(added.kind, AgentKind::Kimi);
        assert_eq!(
            added.model.as_deref(),
            Some("kimi-code/k3"),
            "argv가 유일한 근거인 세션에서 모델을 버리면 안 된다"
        );
        assert_eq!(added.effort.as_deref(), Some("high"));

        let kept = info.get(&rich).expect("기존 항목은 남아야 한다");
        assert_eq!(
            kept.model.as_deref(),
            Some("opus"),
            "transcript 값을 argv 값으로 덮으면 더 나쁜 정보로 후퇴한다"
        );
        assert_eq!(kept.context_pct, Some(42));

        // 헬퍼가 맞아도 **부르지 않으면** 화면은 그대로다 — PR #93이 정확히 그렇게
        // 실패했다(감지는 추가했는데 agent_info까지 잇지 않아 카드에 줄이 없었다).
        // 배선까지 고정한다.
        let source = include_str!("app.rs");
        let body = source
            .split_once("    fn push_agent_display(&mut self) {")
            .and_then(|(_, tail)| tail.split_once("\n    }"))
            .map(|(body, _)| body)
            .expect("push_agent_display 본문을 찾지 못했다");
        assert!(
            body.contains(
                "merge_detected_kinds(&mut merged, &kinds_for_active, &self.agent_bindings)"
            ),
            "병합을 부르지 않으면 프로세스로만 감지된 에이전트가 카드에서 셸로 강등된다"
        );
    }

    /// 은퇴한 runtime_instance 몫만 지우고 다른 instance는 그대로 둔다 — instance A로
    /// 채운 뒤 A가 은퇴하면 A의 항목만 사라지고 B는 남아야 한다(2026-08-14, 코드 리뷰:
    /// 은퇴 정리가 통째로 없었다).
    #[test]
    fn retain_other_runtime_instance는_은퇴한_instance_몫만_지운다() {
        let mut map: std::collections::HashMap<(u64, runtime::SessionId), &str> =
            std::collections::HashMap::from([
                ((1, runtime::SessionId(10)), "a"),
                ((1, runtime::SessionId(11)), "b"),
                ((2, runtime::SessionId(10)), "c"),
            ]);

        retain_other_runtime_instance(&mut map, 1);

        assert_eq!(
            map.len(),
            1,
            "은퇴한 instance 1의 항목은 전부 사라져야 한다"
        );
        assert_eq!(
            map.get(&(2, runtime::SessionId(10))),
            Some(&"c"),
            "다른(살아있는) instance 2의 항목은 남아야 한다"
        );
    }

    /// 헬퍼가 맞아도 **은퇴 지점에서 부르지 않으면** 죽은 runtime_instance의 항목이 앱
    /// 수명 동안 무계로 쌓인다(2026-08-14 코드 리뷰: warm runtime이 shutdown되는 세 지점
    /// 중 정리가 하나도 없었다). 세 은퇴 지점 배선을 전부 고정한다 — App::on_exit의 전체
    /// 종료는 App 자신이 곧 드롭되므로 대상이 아니다.
    #[test]
    fn 은퇴하는_runtime_은_세_지점_모두에서_agent_display_prune을_부른다() {
        let source = include_str!("app.rs");
        const CALL: &str = "self.prune_agent_display_for_retired_instance(";

        let suspend = source
            .split_once("fn suspend_warm_workspace(")
            .unwrap()
            .1
            .split_once("fn join_pending_shutdown")
            .unwrap()
            .0;
        assert!(
            suspend.contains(CALL),
            "suspend_warm_workspace의 실제 suspend 분기가 정리를 부르지 않는다"
        );

        let close = source
            .split_once("fn close_workspace_sessions")
            .unwrap()
            .1
            .split_once("fn reveal_closed_workspace")
            .unwrap()
            .0;
        assert!(
            close.contains(CALL),
            "close_workspace_sessions의 warm 종료 분기가 정리를 부르지 않는다"
        );

        let bench_delete = source
            .split_once("fn bench_delete_workspace(")
            .unwrap()
            .1
            .split_once("fn subscribe_runtime_events")
            .unwrap()
            .0;
        assert!(
            bench_delete.contains(CALL),
            "bench_delete_workspace가 정리를 부르지 않는다"
        );
    }

    /// 계속 막혀 있는 세션의 타이머가 폴링마다 0으로 돌아가면 "오래 막힌 순" 정렬이
    /// 무의미해진다. global_waiting이 스냅샷마다 통째로 재구성되기 때문에 생기는 위험이라
    /// 이 계약을 고정한다(2026-08-08).
    #[test]
    fn 막힌_시각은_계속_막힌_키의_값을_유지한다() {
        use std::collections::{HashMap, HashSet};

        let key = |id: u64| ("ws".to_owned(), runtime::SessionId(id));
        let mut map: HashMap<(String, runtime::SessionId), i64> = HashMap::new();

        // 1) 처음 막힘 — 지금 시각을 찍는다.
        let live: HashSet<_> = [key(1), key(2)].into_iter().collect();
        update_blocked_since(&mut map, &live, 100);
        assert_eq!(map.get(&key(1)), Some(&100));
        assert_eq!(map.get(&key(2)), Some(&100));

        // 2) 같은 키가 계속 막힌 채로 다시 폴링 — 값이 그대로여야 한다.
        update_blocked_since(&mut map, &live, 160);
        assert_eq!(
            map.get(&key(1)),
            Some(&100),
            "계속 막힌 키의 시각을 덮어쓰면 타이머가 0으로 돌아간다"
        );

        // 3) 하나가 풀리고 새 세션이 막힘.
        let live: HashSet<_> = [key(2), key(3)].into_iter().collect();
        update_blocked_since(&mut map, &live, 200);
        assert_eq!(map.get(&key(1)), None, "풀린 키는 제거돼야 한다");
        assert_eq!(map.get(&key(2)), Some(&100), "계속 막힌 키는 유지");
        assert_eq!(map.get(&key(3)), Some(&200), "새로 막힌 키는 지금 시각");

        // 4) 전부 풀리면 비어야 한다 — 맵이 무한히 자라면 안 된다.
        update_blocked_since(&mut map, &HashSet::new(), 300);
        assert!(map.is_empty());
    }

    /// `SessionId`는 워크스페이스마다 재사용된다(런타임별 카운터). 키를
    /// `(workspace_id, SessionId)` 쌍이 아니라 `SessionId` 하나로만 뒀다면, 워크스페이스
    /// A의 세션 1이 계속 막혀 있는 도중 워크스페이스 B의 세션 1이 새로 막히는 순간 A의
    /// 막힌 시각이 B의 것으로 덮이거나 서로 하나의 항목으로 뒤섞인다. 이 테스트는 워크스페이스
    /// 이름을 실제로 키에 넣어 서로 다른 항목으로 남는지를 고정한다.
    #[test]
    fn 막힌_시각은_워크스페이스로_네임스페이스돼_같은_세션id도_구분한다() {
        use std::collections::{HashMap, HashSet};

        let key = |ws: &str, id: u64| (ws.to_owned(), runtime::SessionId(id));
        let mut map: HashMap<(String, runtime::SessionId), i64> = HashMap::new();

        // 1) 워크스페이스 a의 세션 1이 막힌다.
        let live: HashSet<_> = [key("a", 1)].into_iter().collect();
        update_blocked_since(&mut map, &live, 100);
        assert_eq!(map.get(&key("a", 1)), Some(&100));

        // 2) 시간이 흐른 뒤 워크스페이스 b에서 같은 id(1)의 세션이 새로 막힌다 — a의 세션
        //    1은 그 사이 계속 막혀 있었다.
        let live: HashSet<_> = [key("a", 1), key("b", 1)].into_iter().collect();
        update_blocked_since(&mut map, &live, 250);
        assert_eq!(
            map.get(&key("a", 1)),
            Some(&100),
            "워크스페이스 a의 세션 1은 계속 막혀 있었으므로 최초 시각을 유지해야 한다"
        );
        assert_eq!(
            map.get(&key("b", 1)),
            Some(&250),
            "워크스페이스 b의 같은 id(1)는 별도 항목이므로 새로 막힌 시각을 가져야 한다"
        );

        // 3) a의 세션 1이 풀려도 같은 id를 쓰는 b의 세션 1은 영향받지 않아야 한다.
        let live: HashSet<_> = [key("b", 1)].into_iter().collect();
        update_blocked_since(&mut map, &live, 300);
        assert_eq!(map.get(&key("a", 1)), None, "풀린 a의 세션은 제거돼야 한다");
        assert_eq!(
            map.get(&key("b", 1)),
            Some(&250),
            "a의 세션이 풀렸다고 같은 id를 쓰는 b의 세션까지 사라지면 네임스페이스가 깨진 것이다"
        );
    }

    /// 워크스페이스 전환 블록(`switch_workspace`)은 `pty_agent_pending` 등 SessionId만으로
    /// 키가 겹치는 맵들은 지우지만 `blocked_since`는 일부러 지우지 않는다 — 이미
    /// `(workspace_id, SessionId)`로 네임스페이스돼 있어 지울 필요가 없고, 지우면 warm
    /// 워크스페이스에서 계속 막혀 있던 세션의 "오래 막힘" 타이머가 화면을 옮길 때마다
    /// 0으로 리셋돼 「작업」 페이지의 FIFO 정렬(오래 막힌 순)이 무의미해진다. 이 계약은
    /// 런타임 값으로 재현하기 어려워(App 전체 픽스처가 필요) 소스 텍스트 특성화 테스트로
    /// 고정한다 — 누군가 "정리 누락"으로 오인해 `blocked_since.clear()`를 추가하면 잡는다.
    #[test]
    fn 워크스페이스_전환은_blocked_since를_지우지_않는다() {
        let source = include_str!("app.rs");
        let body = source
            .split_once("    fn switch_workspace(&mut self, target_id: &str) {")
            .and_then(|(_, tail)| {
                tail.split_once("    fn cycle_workspace(&mut self, delta: isize) {")
            })
            .map(|(body, _)| body)
            .expect("switch_workspace function remains discoverable");

        assert!(
            !body.contains("self.blocked_since.clear()"),
            "blocked_since는 (workspace_id, SessionId)로 네임스페이스돼 있어 워크스페이스 전환 \
             시 지우면 안 된다 — 지우면 warm 워크스페이스 세션의 「오래 막힘」 타이머가 화면을 \
             옮길 때마다 0으로 리셋된다"
        );
    }

    /// app-server가 아직 없거나 일부 창만 보고해도 백엔드가 읽은 창으로 빈칸만
    /// 채운다. app-server 값이 있으면 언제나 그 값이 우선한다.
    #[test]
    fn codex_백엔드는_server의_빈_사용량_창만_채운다() {
        /// (설명, 서버 값, 백엔드 값, 기대 결과) — 튜플이 길어 clippy
        /// `type_complexity`에 걸린다. 표를 그대로 두면서 이름만 붙인다.
        type Case = (
            &'static str,
            Option<ProviderUsage>,
            Option<crate::codex_backend_usage::BackendUsage>,
            Option<ProviderUsage>,
        );
        let cases: &[Case] = &[
            (
                "server 없음 + backend 주간 → backend 표시",
                None,
                Some(crate::codex_backend_usage::BackendUsage {
                    five_hour: None,
                    weekly: Some(2),
                }),
                Some((None, Some(2))),
            ),
            (
                "server 주간만 + backend 양쪽 → 5시간만 보충",
                Some((None, Some(91))),
                Some(crate::codex_backend_usage::BackendUsage {
                    five_hour: Some(24),
                    weekly: Some(99),
                }),
                Some((Some(24), Some(91))),
            ),
            (
                "server 양쪽 + backend 양쪽 → server 유지",
                Some((Some(12), Some(91))),
                Some(crate::codex_backend_usage::BackendUsage {
                    five_hour: Some(99),
                    weekly: Some(98),
                }),
                Some((Some(12), Some(91))),
            ),
            (
                "server 5시간만 + backend 주간 → 주간만 보충",
                Some((Some(12), None)),
                Some(crate::codex_backend_usage::BackendUsage {
                    five_hour: Some(99),
                    weekly: Some(88),
                }),
                Some((Some(12), Some(88))),
            ),
            ("양쪽 모두 없음", None, None, None),
        ];
        for (name, server, backend, expected) in cases {
            assert_eq!(merge_codex_usage(*server, *backend), *expected, "{name}");
        }
    }

