    /// `Waiting`은 **입력 대기**(보내도 됨)와 **승인 대기**(보내면 안 됨)를 뭉갠다.
    /// 시각 상태만 보고 막으면 프롬프트에서 놀고 있는 에이전트에 단축키가 전혀
    /// 반응하지 않고(2026-08-02 실증), 허용하면 승인 질문에 엉뚱한 답이 들어간다.
    #[test]
    fn 응답과_승인_대기에는_슬래시_명령을_보내지_않는다() {
        use crate::agent_surface::{
            AgentProvider, AgentSurfaceId, AgentSurfaceSnapshot, AgentTransport, AgentVisualState,
        };
        use runtime::SessionStatus as Status;

        let surface = |status: Option<Status>| AgentSurfaceSnapshot {
            id: AgentSurfaceId::Pty {
                workspace_id: "ws".to_owned(),
                pane_id: "pane".to_owned(),
                session_id: runtime::SessionId(1),
            },
            provider: AgentProvider::Claude,
            transport: AgentTransport::Pty,
            title: "claude".to_owned(),
            model: None,
            effort: None,
            context_pct: None,
            state: AgentVisualState::from_pty(status),
            pty_status: status,
        };

        // 질문과 승인은 구분해서 표시하며 둘 다 임의 명령을 답으로 보내지 않는다.
        assert_ne!(
            surface(Some(Status::Waiting)).state,
            surface(Some(Status::NeedsApproval)).state
        );
        assert!(!slash_input_is_safe(&surface(Some(Status::Waiting)), None));
        // 사유를 모르면 승인으로 보고 막는다.
        assert!(!slash_input_is_safe(
            &surface(Some(Status::NeedsApproval)),
            None
        ));

        assert!(slash_input_is_safe(&surface(Some(Status::Idle)), None));
        assert!(slash_input_is_safe(&surface(Some(Status::Done)), None));
        assert!(!slash_input_is_safe(&surface(Some(Status::Running)), None));
        // 미분류는 보수적으로 허용(에이전트 없음 = 셸 프롬프트).
        assert!(slash_input_is_safe(&surface(None), None));
    }

    /// hook needsInput은 유휴 프롬프트에도 오는데, merge_agent_status가 그걸 승인 대기와
    /// 같은 NeedsApproval로 접는다. 문구로 가르지 않으면 프롬프트에서 놀고 있는 claude가
    /// 영원히 "작업 중"으로 막혀 단축키가 큐에만 쌓인다(2026-08-03 실증: 40분 묵은
    /// "Claude is waiting for your input" 행 하나 때문에 강도 변경이 전부 무시됐다).
    #[test]
    fn hook_유휴_프롬프트_문구는_승인_대기를_열어준다() {
        use crate::agent_surface::{
            AgentProvider, AgentSurfaceId, AgentSurfaceSnapshot, AgentTransport, AgentVisualState,
        };
        use runtime::SessionStatus as Status;

        let surface = AgentSurfaceSnapshot {
            id: AgentSurfaceId::Pty {
                workspace_id: "ws".to_owned(),
                pane_id: "pane".to_owned(),
                session_id: runtime::SessionId(1),
            },
            provider: AgentProvider::Claude,
            transport: AgentTransport::Pty,
            title: "claude".to_owned(),
            model: None,
            effort: None,
            context_pct: None,
            state: AgentVisualState::from_pty(Some(Status::NeedsApproval)),
            pty_status: Some(Status::NeedsApproval),
        };

        // 실제 hook이 보내는 문구 그대로.
        assert!(slash_input_is_safe(
            &surface,
            Some("Claude is waiting for your input")
        ));
        // 승인 프롬프트는 여전히 막힌다 — 화이트리스트라 모르는 문구는 전부 불허.
        assert!(!slash_input_is_safe(
            &surface,
            Some("Claude needs your permission to use Bash")
        ));
        assert!(!slash_input_is_safe(&surface, Some("")));
        assert!(!slash_input_is_safe(&surface, None));
    }

    #[test]
    fn cross_workspace_app_attached_focus_blocks_only_primary_terminal_shortcuts() {
        use crate::shortcuts::ShortcutAction as A;

        for action in [
            A::NewShell,
            A::ClosePane,
            A::SplitVertical,
            A::SplitHorizontal,
            A::FocusNextPane,
            A::FocusPreviousPane,
            A::TerminalSearch,
            A::ScrollToBottom,
            A::PromptJumpPrev,
            A::PromptJumpNext,
        ] {
            assert!(shortcut_targets_primary_terminal(action), "{action:?}");
        }
        for action in [
            A::NextWorkspace,
            A::PreviousWorkspace,
            A::IncreaseTerminalFont,
            A::DecreaseTerminalFont,
            A::ClearRenderCaches,
            A::ToggleSidebar,
            A::OpenEnvironment,
            A::FocusComposer,
        ] {
            assert!(!shortcut_targets_primary_terminal(action), "{action:?}");
        }
        assert!(shortcut_depends_on_terminal_owner(A::FocusComposer));
    }

    #[test]
    fn cross_workspace_app_pointer_transition_blocks_only_terminal_shortcuts() {
        use crate::shortcuts::ShortcutAction as A;
        let terminal_rect =
            egui::Rect::from_min_size(egui::pos2(100.0, 80.0), egui::vec2(900.0, 700.0));
        let inside = pointer_transition_inside_rect(
            Some(terminal_rect),
            true,
            Some(egui::pos2(400.0, 300.0)),
        );
        let outside = pointer_transition_inside_rect(
            Some(terminal_rect),
            true,
            Some(egui::pos2(40.0, 300.0)),
        );

        assert!(configured_terminal_shortcut_blocked(
            A::ClosePane,
            false,
            inside,
        ));
        assert!(configured_terminal_shortcut_blocked(
            A::FocusComposer,
            false,
            inside,
        ));
        assert!(configured_terminal_shortcut_blocked(
            A::TerminalSearch,
            true,
            false,
        ));
        assert!(!configured_terminal_shortcut_blocked(
            A::ClosePane,
            false,
            outside,
        ));
        assert!(!configured_terminal_shortcut_blocked(
            A::FocusComposer,
            true,
            false,
        ));
        assert!(!configured_terminal_shortcut_blocked(
            A::ToggleSidebar,
            false,
            inside,
        ));
    }

