    /// 구분 가능한 최소 MuxUpdated 이벤트 (active_tab 태그로 스냅샷을 식별).
    fn mux_event(tag: &str) -> runtime::RuntimeEvent {
        runtime::RuntimeEvent::MuxUpdated {
            snapshot: std::sync::Arc::new(runtime::MuxSnapshot {
                tabs: Vec::new(),
                active_tab: Some(runtime::MuxTabId(tag.to_owned())),
                focused_pane: None,
            }),
        }
    }

    fn live_mux_event(tag: &str, sessions: &[u64]) -> runtime::RuntimeEvent {
        runtime::RuntimeEvent::MuxUpdated {
            snapshot: std::sync::Arc::new(runtime::MuxSnapshot {
                tabs: vec![runtime::TabSnapshot {
                    id: runtime::MuxTabId(tag.to_owned()),
                    title: tag.to_owned(),
                    layout: runtime::LayoutNode::Pane(runtime::MuxPaneId(format!(
                        "{tag}-pane-{}",
                        sessions.first().copied().unwrap_or(0)
                    ))),
                    panes: sessions
                        .iter()
                        .map(|session| runtime::PaneSnapshot {
                            id: runtime::MuxPaneId(format!("{tag}-pane-{session}")),
                            session_id: Some(runtime::SessionId(*session)),
                            title: format!("session-{session}"),
                            persistent_session_id: None,
                        })
                        .collect(),
                }],
                active_tab: Some(runtime::MuxTabId(tag.to_owned())),
                focused_pane: sessions
                    .first()
                    .map(|session| runtime::MuxPaneId(format!("{tag}-pane-{session}"))),
            }),
        }
    }

    fn mux_tag(e: &runtime::RuntimeEvent) -> Option<&str> {
        match e {
            runtime::RuntimeEvent::MuxUpdated { snapshot } => {
                snapshot.active_tab.as_ref().map(|t| t.0.as_str())
            }
            _ => None,
        }
    }

    fn workspace_with_pending_shell(cwd: &str) -> ui::workspace::WorkspaceUi {
        let mut workspace_ui = ui::workspace::WorkspaceUi::new();
        workspace_ui.spawn_shell_at(1_000, Some(cwd.to_owned()));
        let intent = workspace_ui.take_protocol_intent().unwrap();
        let operation = intent.operation();
        let generation = intent.generation();
        workspace_ui.complete_protocol(ui::workspace::WorkspaceProtocolCompletion {
            operation,
            generation,
            result: Ok(()),
        });
        assert_eq!(workspace_ui.pending_spawns(), 1);
        workspace_ui
    }

    #[test]
    fn workspace_protocol_delivery_maps_runtime_pressure_separately_from_disconnect() {
        assert_eq!(
            classify_workspace_protocol_delivery(Err(
                runtime::RuntimeCommandSendError::Backpressure.into()
            )),
            Err(ui::workspace::WorkspaceProtocolErrorCode::Busy)
        );
        assert_eq!(
            classify_workspace_protocol_delivery(Err(
                runtime::RuntimeCommandSendError::Disconnected.into()
            )),
            Err(ui::workspace::WorkspaceProtocolErrorCode::DeliveryFailed)
        );
        assert_eq!(classify_workspace_protocol_delivery(Ok(())), Ok(()));
    }

    fn overflow_spawn_replay(
        completion: runtime::RuntimeEvent,
    ) -> (
        ui::workspace::WorkspaceUi,
        Vec<runtime::RuntimeEvent>,
        ReplayCompaction,
    ) {
        let mut workspace_ui = workspace_with_pending_shell("/tmp/deppy-spawn");
        let mut events = vec![completion];
        events.extend((0..=PENDING_REPLAY_EVENT_CAP).map(|idx| {
            runtime::RuntimeEvent::SpawnFailed {
                kind: runtime::SpawnKind::Agent,
                message: runtime::MessagePayload::new(format!("agent.failed.{idx}")),
            }
        }));
        let mut pending_events = Vec::new();
        let compacted = admit_hidden_active_replay_events(
            &mut workspace_ui,
            &mut pending_events,
            events,
            &i18n::Catalog::load(i18n::FALLBACK_LOCALE).unwrap(),
        );
        (workspace_ui, pending_events, compacted)
    }

    fn resource_event(sampled_at_ms: u64) -> runtime::RuntimeEvent {
        runtime::RuntimeEvent::ResourceUsage {
            snapshot: runtime::ProcessResourceSnapshot {
                pid: 42,
                sampled_at_ms,
                rss_bytes: sampled_at_ms * 1024,
                cpu_percent: Some(sampled_at_ms as f32),
                high_cpu: false,
                high_rss: false,
            },
            session_usage: Vec::new(),
        }
    }

    fn input_pressure_event(session: u64, queued_bytes: usize) -> runtime::RuntimeEvent {
        runtime::RuntimeEvent::PtyInputPressure {
            session: runtime::SessionId(session),
            pressure: runtime::PtyInputPressure {
                attempted_bytes: queued_bytes + 1,
                queued_bytes,
                queued_messages: 1,
                max_bytes: 1024,
                max_messages: 8,
                reason: runtime::PtyInputRejectReason::QueueFull,
            },
        }
    }

    fn viewport_event(session: u64, title: &str) -> runtime::RuntimeEvent {
        runtime::RuntimeEvent::Viewport {
            session: runtime::SessionId(session),
            snapshot: std::sync::Arc::new(terminal::TerminalViewportSnapshot {
                cols: 0,
                rows: 0,
                cursor: terminal::CursorSnapshot {
                    col: 0,
                    row: 0,
                    shape: terminal::CursorShape::Block,
                    visible: false,
                },
                visible_cells: Vec::new().into(),
                dirty_ranges: Vec::new(),
                title: Some(title.to_owned()),
                scroll_offset: 0,
                is_alt_screen: false,
            }),
            bracketed_paste: false,
        }
    }

    fn temp_db_path(name: &str) -> PathBuf {
        let nanos = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .unwrap()
            .as_nanos();
        std::env::temp_dir().join(format!(
            "deppy-sijo-{name}-{}-{nanos}.sqlite3",
            std::process::id()
        ))
    }

    fn app_file_tree_watch_temp_root(tag: &str) -> PathBuf {
        let dir = std::env::temp_dir().join(format!(
            "deppy-app-file-tree-watch-{tag}-{}-{}",
            std::process::id(),
            uuid::Uuid::new_v4()
        ));
        std::fs::create_dir_all(&dir).unwrap();
        dir
    }

    /// `ui::file_tree::FileTreeMaintenanceOperation`의 내부 필드는 `file_tree` 모듈
    /// 밖에서 만들 수 없다 — 그래서 실제 `FileTreeUi` 왕복(set_root → listing 완료 →
    /// watch plan)을 그대로 밟아 유효한 (operation, generation, plan) 값을 얻는다.
    fn app_file_tree_watch_intent(
        tree: &mut ui::file_tree::FileTreeUi,
        root: PathBuf,
    ) -> (
        ui::file_tree::FileTreeMaintenanceOperation,
        u64,
        Vec<PathBuf>,
        Vec<PathBuf>,
        bool,
    ) {
        tree.set_root(Some(root));
        let listing_intent = tree
            .take_maintenance_intent()
            .expect("set_root produces a listing intent first");
        tree.complete_maintenance(ui::file_tree::FileTreeMaintenanceCompletion {
            operation: listing_intent.operation,
            generation: listing_intent.generation,
            result: Ok(ui::file_tree::FileTreeMaintenanceResult::Listing(
                ui::file_tree::FileTreeListingSnapshot::try_new(Vec::new()).unwrap(),
            )),
        });
        let watch_intent = tree
            .take_maintenance_intent()
            .expect("an empty listing completion drives a watch plan intent next");
        let operation = watch_intent.operation;
        let generation = watch_intent.generation;
        let ui::file_tree::FileTreeMaintenanceRequest::ReplaceWatchSet(plan) = watch_intent.request
        else {
            panic!("expected a ReplaceWatchSet intent");
        };
        let (directories, ignored_prefixes, show_hidden) = plan.into_parts();
        (
            operation,
            generation,
            directories,
            ignored_prefixes,
            show_hidden,
        )
    }

    #[test]
    fn app_file_tree_watcher_submit_replace는_즉시_반환하고_완료는_나중에_도착한다() {
        let root = app_file_tree_watch_temp_root("submit-replace");
        let ctx = egui::Context::default();
        let mut tree = ui::file_tree::FileTreeUi::new(ctx.clone());
        let (operation, generation, directories, ignored_prefixes, show_hidden) =
            app_file_tree_watch_intent(&mut tree, root.clone());

        let mut watcher = AppFileTreeWatcher::new(ctx).expect("watcher spawns");
        let submitted_at = std::time::Instant::now();
        watcher
            .submit_replace(
                operation,
                generation,
                directories,
                ignored_prefixes,
                show_hidden,
            )
            .expect("submit accepted");
        // submit_replace는 watch()/unwatch()를 직접 호출하지 않는다 — 그 증거로 반환
        // 직후에는 아직 필터 메타데이터가 갱신돼 있지 않다. 적용은 워커의 비동기
        // 완료(poll_completion) 이후에만 일어난다.
        assert!(submitted_at.elapsed() < std::time::Duration::from_millis(50));
        assert_eq!(watcher.root, PathBuf::new());
        assert_eq!(watcher.generation, 0);

        // submit 지연 계약은 위의 50ms assertion이 따로 검증한다. 이 watchdog은
        // macOS FSEvents 서버 등록 완료만 기다린다. 동시 watcher 부하에서
        // FSEventStreamStart RPC가 5초를 넘기는 경로를 sample로 확인했으므로,
        // OS 스케줄링 지연을 submit_replace 회귀로 오판하지 않도록 분리한다.
        let deadline = std::time::Instant::now() + std::time::Duration::from_secs(30);
        let completion = loop {
            if let Some(completion) = watcher.poll_completion() {
                break completion;
            }
            assert!(
                std::time::Instant::now() < deadline,
                "watch completion timed out"
            );
            std::thread::sleep(std::time::Duration::from_millis(5));
        };
        assert_eq!(completion.operation, operation);
        assert_eq!(completion.generation, generation);
        assert!(
            completion.result.is_ok(),
            "watch apply failed: {:?}",
            completion.result.err()
        );
        assert_eq!(watcher.root, root);
        assert_eq!(watcher.generation, generation);

        drop(watcher);
        std::fs::remove_dir_all(&root).ok();
    }

    #[test]
    fn app_file_tree_watcher_stale_generation_완료는_메타데이터를_되돌리지_않는다() {
        let root1 = app_file_tree_watch_temp_root("stale-root1");
        let root2 = app_file_tree_watch_temp_root("stale-root2");
        let ctx = egui::Context::default();
        let mut tree = ui::file_tree::FileTreeUi::new(ctx.clone());
        let (op1, gen1, _dirs1, _ignored1, _hidden1) =
            app_file_tree_watch_intent(&mut tree, root1.clone());
        let (op2, gen2, _dirs2, ignored2, hidden2) =
            app_file_tree_watch_intent(&mut tree, root2.clone());
        assert_ne!((op1, gen1), (op2, gen2));

        let mut watcher = AppFileTreeWatcher::new(ctx).expect("watcher spawns");
        // 실제로는 submit_replace가 이 값을 세팅하지만, 여기서는 stale-guard 로직만
        // 직접 검증하기 위해 "op2/gen2가 현재 in-flight" 상태를 미리 만들어 둔다.
        watcher.pending_operation = Some((op2, gen2));

        // 더 이전(op1,gen1) 요청의 완료가 op2를 보낸 뒤 뒤늦게 도착한 상황을 흉내낸다.
        let stale = AppFileTreeWatchCompletion {
            operation: op1,
            generation: gen1,
            result: Ok(AppFileTreeWatchApplied {
                root: root1.clone(),
                ignored_prefixes: Vec::new(),
                show_hidden: false,
            }),
        };
        watcher.apply_completion_metadata(&stale);
        // stale 완료는 무시된다 — root/generation은 여전히 초기값이고, op2가 아직
        // in-flight로 남아 있어야 한다(최신 요청의 root보다 뒤로 되돌아가면 안 된다).
        assert_eq!(watcher.root, PathBuf::new());
        assert_eq!(watcher.generation, 0);
        assert_eq!(watcher.pending_operation, Some((op2, gen2)));

        // 진짜 in-flight 요청(op2,gen2)의 완료가 도착하면 그때는 반영된다.
        let current = AppFileTreeWatchCompletion {
            operation: op2,
            generation: gen2,
            result: Ok(AppFileTreeWatchApplied {
                root: root2.clone(),
                ignored_prefixes: ignored2,
                show_hidden: hidden2,
            }),
        };
        watcher.apply_completion_metadata(&current);
        assert_eq!(watcher.root, root2);
        assert_eq!(watcher.generation, gen2);
        assert!(watcher.pending_operation.is_none());

        drop(watcher);
        std::fs::remove_dir_all(&root1).ok();
        std::fs::remove_dir_all(&root2).ok();
    }

    /// P2-B 재현/회귀용: 실제 워커 스레드 대신 테스트가 `request_rx`를 직접 쥐고
    /// recv() 시점을 통제한다 — 실제 워커는 job을 즉시(또는 워크로드에 따라 최대
    /// 115ms 안에) 소비하므로 `Full`을 결정론적으로 재현할 수 없다. `handle`은
    /// 아무 일도 하지 않고 즉시 끝나는 스레드라 watcher Drop의 join()이 절대
    /// 블로킹하지 않는다.
    fn app_file_tree_watcher_with_manual_channel() -> (
        AppFileTreeWatcher,
        std::sync::mpsc::Receiver<AppFileTreeWatchJob>,
    ) {
        let (request_tx, request_rx) = std::sync::mpsc::sync_channel::<AppFileTreeWatchJob>(1);
        let (_completion_tx, completion_rx) =
            std::sync::mpsc::sync_channel::<AppFileTreeWatchCompletion>(1);
        let handle = std::thread::spawn(|| {});
        let watcher = AppFileTreeWatcher {
            slot: Some(AppFileTreeWatcherSlot {
                request_tx,
                completion_rx,
                handle,
            }),
            pending_operation: None,
            retry: None,
            pending: Arc::new(std::sync::Mutex::new(PendingFileTreeWatchEvents::default())),
            generation: 0,
            revision: 0,
            root: PathBuf::new(),
            ignored_prefixes: Vec::new(),
            show_hidden: false,
        };
        (watcher, request_rx)
    }

    #[test]
    fn app_file_tree_watcher_submit_replace_full은_폐기하지_않고_재시도로_보관한다() {
        let root = app_file_tree_watch_temp_root("full-retry");
        let ctx = egui::Context::default();
        let mut tree = ui::file_tree::FileTreeUi::new(ctx.clone());
        let (op1, gen1, dirs1, ignored1, hidden1) =
            app_file_tree_watch_intent(&mut tree, root.clone());
        let (op2, gen2, dirs2, ignored2, hidden2) =
            app_file_tree_watch_intent(&mut tree, root.clone());

        let (mut watcher, request_rx) = app_file_tree_watcher_with_manual_channel();

        // 첫 submit: 채널(capacity 1)이 비어 있으니 성공하고 버퍼를 채운다. 아무도
        // recv()하지 않으므로 이 job은 "아직 recv되지 않은 이전 job"으로 남는다.
        watcher
            .submit_replace(op1, gen1, dirs1, ignored1, hidden1)
            .expect("first submit fills the channel");
        assert_eq!(watcher.pending_operation, Some((op1, gen1)));
        assert!(watcher.retry.is_none());

        // 두 번째 submit: try_send가 Full을 맞는다. 구 코드라면 여기서 즉시
        // Err(WatchUnavailable)이 나와 호출자가 watcher를 폐기했다 — 새 코드는 Ok(())를
        // 주고 job을 retry에 보관해야 한다.
        let result = watcher.submit_replace(op2, gen2, dirs2, ignored2, hidden2);
        assert!(
            result.is_ok(),
            "Full은 즉시 실패가 아니라 재시도로 보관돼야 한다: {result:?}"
        );
        assert!(watcher.retry.is_some(), "job이 retry에 보관돼야 한다");
        // pending_operation은 여전히 실제로 채널에 남아 있는 op1을 가리켜야 한다 — 아직
        // 전송되지 않은 op2로 덮어쓰면 op1의 완료가 도착했을 때 stale-guard가 깨진다.
        assert_eq!(watcher.pending_operation, Some((op1, gen1)));

        // poll_retry(): 채널이 여전히 Full이니 재시도를 계속 보관하고(완료 소식 없음).
        assert!(watcher.poll_retry().is_none());
        assert!(watcher.retry.is_some());

        // 실제 워커가 op1 job을 recv해 처리하기 시작한 상황을 흉내낸다 — 채널에 여유가
        // 생긴다.
        let drained = request_rx.recv().expect("op1 job still queued");
        assert_eq!(drained.operation, op1);

        // 다음 폴(poll_retry)에서 자연 재시도가 성공해야 한다.
        assert!(
            watcher.poll_retry().is_none(),
            "재전송 성공 -- 아직 완료 소식은 없다"
        );
        assert!(
            watcher.retry.is_none(),
            "재전송에 성공했으니 retry는 비워져야 한다"
        );
        assert_eq!(watcher.pending_operation, Some((op2, gen2)));
        let resent = request_rx.recv().expect("op2 job now in the channel");
        assert_eq!(resent.operation, op2);

        drop(watcher);
        std::fs::remove_dir_all(&root).ok();
    }

    #[test]
    fn app_file_tree_watcher_submit_replace_disconnected는_기존_폐기_경로_그대로다() {
        let root = app_file_tree_watch_temp_root("disconnected");
        let ctx = egui::Context::default();
        let mut tree = ui::file_tree::FileTreeUi::new(ctx.clone());
        let (op, generation, dirs, ignored, hidden) =
            app_file_tree_watch_intent(&mut tree, root.clone());

        let (mut watcher, request_rx) = app_file_tree_watcher_with_manual_channel();
        // 워커 스레드가 이미 죽어 request_rx가 드롭된 상황을 흉내낸다.
        drop(request_rx);

        let result = watcher.submit_replace(op, generation, dirs, ignored, hidden);
        assert!(
            matches!(
                result,
                Err(ui::file_tree::FileTreeMaintenanceErrorCode::WatchUnavailable)
            ),
            "Disconnected는 기존처럼 즉시 에러여야 한다: {result:?}"
        );
        // Disconnected는 재시도 대상이 아니다 -- 호출자가 즉시 폐기 경로를 타야 한다.
        assert!(watcher.retry.is_none());
        assert!(watcher.pending_operation.is_none());

        drop(watcher);
        std::fs::remove_dir_all(&root).ok();
    }

    #[test]
    fn app_file_tree_watcher_full_재시도가_상한을_넘기면_폐기_경로로_넘어간다() {
        let root = app_file_tree_watch_temp_root("full-retry-timeout");
        let ctx = egui::Context::default();
        let mut tree = ui::file_tree::FileTreeUi::new(ctx.clone());
        let (op1, gen1, dirs1, ignored1, hidden1) =
            app_file_tree_watch_intent(&mut tree, root.clone());
        let (op2, gen2, dirs2, ignored2, hidden2) =
            app_file_tree_watch_intent(&mut tree, root.clone());

        let (mut watcher, _request_rx) = app_file_tree_watcher_with_manual_channel();
        watcher
            .submit_replace(op1, gen1, dirs1, ignored1, hidden1)
            .expect("first submit fills the channel");
        watcher
            .submit_replace(op2, gen2, dirs2, ignored2, hidden2)
            .expect("second submit is deferred to retry, not an immediate error");
        let (job, _started_at) = watcher.retry.take().expect("op2 job stored for retry");

        // 재시도 시작 시각을 상한보다 더 과거로 조작해 "오래 Full이 지속됐다"를
        // 흉내낸다 -- _request_rx를 계속 drain하지 않으므로 채널은 여전히 Full이다.
        let stale_started_at = std::time::Instant::now()
            .checked_sub(APP_FILE_TREE_WATCH_RETRY_TIMEOUT + std::time::Duration::from_millis(50))
            .expect("timeout margin fits");
        watcher.retry = Some((job, stale_started_at));

        let completion = watcher
            .poll_retry()
            .expect("재시도 상한을 넘기면 기존 폐기 경로로 넘어갈 실패 completion을 줘야 한다");
        assert_eq!(completion.operation, op2);
        assert_eq!(completion.generation, gen2);
        assert!(matches!(
            completion.result,
            Err(ui::file_tree::FileTreeMaintenanceErrorCode::WatchUnavailable)
        ));
        assert!(watcher.retry.is_none());

        drop(watcher);
        std::fs::remove_dir_all(&root).ok();
    }

    fn sqlite_sidecar(path: &Path, suffix: &str) -> PathBuf {
        let mut file_name = path.as_os_str().to_owned();
        file_name.push(suffix);
        PathBuf::from(file_name)
    }

    fn remove_sqlite_files(path: &Path) {
        let _ = std::fs::remove_file(path);
        let _ = std::fs::remove_file(sqlite_sidecar(path, "-wal"));
        let _ = std::fs::remove_file(sqlite_sidecar(path, "-shm"));
    }

