    #[test]
    fn approval_launch_tracker는_denial실패를_bounded_backoff한다() {
        let now = std::time::Instant::now();
        let mut tracker = ApprovalLaunchTracker::default();
        let ticket = tracker
            .reserve("ws".to_owned(), "agent".to_owned(), now)
            .unwrap();
        assert!(tracker.mark_spawn_sent(ticket, now));
        assert!(tracker.correlate("ws", "agent", Some(runtime::SessionId(43))));
        assert!(tracker.observe_session_exit("ws", runtime::SessionId(43)));
        tracker.mark_deny_queued("ws", runtime::SessionId(43));
        assert_eq!(
            tracker.finish_session("ws", runtime::SessionId(43), false, now),
            Some(std::time::Duration::from_secs(1))
        );
        for _ in 0..300 {
            assert!(tracker.pending_denials(now).is_empty());
        }
        assert_eq!(
            tracker.pending_denials(now + std::time::Duration::from_secs(1)),
            vec![("ws".to_owned(), runtime::SessionId(43))]
        );
        assert_eq!(tracker.denial_retries.len(), 1);
        assert_eq!(tracker.live.len(), 1);
    }

    #[test]
    fn workspace_sources_worker는_명시한_파일과_중지만_전달한다() {
        let path = temp_db_path("sources-worker");
        let db = Db::open(&path).unwrap();
        let workspace = db.create_workspace("sources-worker").unwrap();
        let dir =
            std::env::temp_dir().join(format!("deppy-sources-worker-{}", uuid::Uuid::new_v4()));
        std::fs::create_dir_all(&dir).unwrap();
        std::fs::write(dir.join(".env"), "PORT=ignored\n").unwrap();
        std::fs::write(dir.join("service.env"), "PORT=selected\n").unwrap();
        db.set_env_source_files(&workspace, Some(&["service.env".into()]))
            .unwrap();
        let mut resource = AppDotenvResource {
            db_path: path,
            db: Some(db),
            redaction: secret::RedactionService::new(),
        };
        let job = || DotenvSyncJob {
            workspace_id: workspace.clone(),
            root: Some(dir.clone()),
            runtime_instance: 1,
            previous_state: None,
            force: true,
            migrate_legacy: false,
        };
        let outcome = execute_dotenv_sync_job(&mut resource, job()).unwrap();
        assert_eq!(outcome.source_files, vec!["service.env"]);
        let mut payload = outcome.payload.unwrap();
        assert_eq!(payload.env_plain, vec![("PORT".into(), "selected".into())]);
        assert!(!payload.source_failed);
        configure_dotenv_live_reload(&mut payload, true, Some(&dir));
        assert_eq!(payload.env_plain.last().unwrap().1, "0");
        resource
            .db
            .as_ref()
            .unwrap()
            .set_env_source_files(&workspace, Some(&[]))
            .unwrap();
        let stopped = execute_dotenv_sync_job(&mut resource, job()).unwrap();
        assert_ne!(outcome.baseline, stopped.baseline);
        let stopped = stopped.payload.unwrap();
        assert!(stopped.env_plain.is_empty());
        assert!(stopped.env_secrets.is_empty());
        assert!(stopped.dotenv_source.unwrap().files.is_empty());
        let mut no_root = job();
        no_root.root = None;
        assert!(
            execute_dotenv_sync_job(&mut resource, no_root)
                .unwrap()
                .payload
                .unwrap()
                .dotenv_source
                .is_some()
        );
        std::fs::remove_dir_all(dir).unwrap();
    }

    #[test]
    fn environment_review_worker의_이전_연결과_파일선택은_설정변경후_인정하지_않는다() {
        let path = temp_db_path("environment-review-stale");
        let db = Db::open(&path).unwrap();
        let workspace = db.create_workspace("generation").unwrap();
        db.insert_credential(&storage::CredentialMeta {
            id: "review-key".into(),
            provider: "service".into(),
            label: "test".into(),
            credential_kind: "api_key".into(),
            masked_hint: None,
            workspace_id: Some(workspace.clone()),
        })
        .unwrap();
        db.set_credential_env_binding(&workspace, "review-key", Some("SERVICE_TOKEN"))
            .unwrap();
        let mut resource = AppDotenvResource {
            db_path: path,
            db: Some(db),
            redaction: secret::RedactionService::new(),
        };
        let mut state = crate::environment_application::EnvironmentApplication::default();
        let job = || DotenvSyncJob {
            workspace_id: workspace.clone(),
            root: None,
            runtime_instance: 1,
            previous_state: None,
            force: false,
            migrate_legacy: false,
        };
        let captured = state.settings_generation();
        let late = execute_dotenv_sync_job(&mut resource, job()).unwrap();
        assert_eq!(late.payload.as_ref().unwrap().api_secrets.len(), 1);
        let db = resource.db.as_ref().unwrap();
        db.set_credential_env_binding(&workspace, "review-key", None)
            .unwrap();
        db.set_env_source_files(&workspace, Some(&[])).unwrap();
        state.changed();
        let fresh = execute_dotenv_sync_job(&mut resource, job()).unwrap();
        assert_eq!(
            late.baseline, fresh.baseline,
            "파일 stamp만으로는 변경을 구분하지 못한다"
        );
        assert!(!state.accepts_settings_generation(captured));
        assert!(state.accepts_settings_generation(state.settings_generation()));
        let payload = fresh.payload.unwrap();
        assert!(payload.api_secrets.is_empty());
        assert!(payload.dotenv_source.unwrap().files.is_empty());
    }

    #[test]
    fn credential_env_환경파일_없이도_실행참조를_읽고_연결해제를_반영한다() {
        let path = temp_db_path("credential-env-payload");
        let db = Db::open(&path).unwrap();
        let workspace = db.create_workspace("credential-env-payload").unwrap();
        db.insert_credential(&storage::CredentialMeta {
            id: "api-credential".into(),
            provider: "service".into(),
            label: "test".into(),
            credential_kind: "api_key".into(),
            masked_hint: None,
            workspace_id: Some(workspace.clone()),
        })
        .unwrap();
        db.set_credential_env_binding(&workspace, "api-credential", Some("SERVICE_KEY"))
            .unwrap();
        let mut resource = AppDotenvResource {
            db_path: path,
            db: Some(db),
            redaction: secret::RedactionService::new(),
        };
        let job = || DotenvSyncJob {
            workspace_id: workspace.clone(),
            root: None,
            runtime_instance: 1,
            previous_state: None,
            force: true,
            migrate_legacy: false,
        };
        let mut payload = execute_dotenv_sync_job(&mut resource, job())
            .unwrap()
            .payload
            .unwrap();
        assert_eq!(
            payload.revision,
            execute_dotenv_sync_job(&mut resource, job())
                .unwrap()
                .payload
                .unwrap()
                .revision
        );
        assert_eq!(
            payload.api_secrets,
            vec![("SERVICE_KEY".into(), "api-credential".into())]
        );
        assert!(payload.env_plain.is_empty());
        assert!(payload.env_secrets.is_empty());
        payload
            .env_plain
            .push(("DEPPY_ENV_LIVE_RELOAD".into(), "1".into()));
        configure_dotenv_live_reload(&mut payload, true, Some(std::path::Path::new("/tmp")));
        assert_eq!(
            payload.env_plain,
            vec![("DEPPY_ENV_LIVE_RELOAD".into(), "0".into())]
        );
        // 파일만 읽지 못해도 검증된 API 연결은 새 실행에 전달한다.
        let dir = std::env::temp_dir().join(format!("deppy-api-source-{}", uuid::Uuid::new_v4()));
        std::fs::create_dir_all(&dir).unwrap();
        std::fs::write(dir.join(".env"), [0xff]).unwrap();
        let mut source_job = job();
        source_job.root = Some(dir.clone());
        let source_payload = execute_dotenv_sync_job(&mut resource, source_job)
            .unwrap()
            .payload
            .unwrap();
        assert!(source_payload.source_failed);
        assert_eq!(source_payload.api_secrets, payload.api_secrets);
        assert!(source_payload.env_plain.is_empty());
        assert!(source_payload.env_secrets.is_empty());
        std::fs::remove_dir_all(dir).unwrap();
        resource
            .db
            .as_ref()
            .unwrap()
            .set_credential_env_binding(&workspace, "api-credential", None)
            .unwrap();
        let unbound = execute_dotenv_sync_job(&mut resource, job())
            .unwrap()
            .payload
            .unwrap();
        assert!(unbound.api_secrets.is_empty());
        assert_ne!(unbound.revision, payload.revision);
    }

