    /// dispatch_respawn_archived_agent가 기대는 판정 — App Server writer 충돌은
    /// **codex** provider + **같은 thread id**가 attach돼 있을 때만 성립한다.
    #[test]
    fn attached_app_server_conflict은_codex_thread가_attach됐을_때만_잡는다() {
        let codex_row = archived_resume_row(
            "p",
            "deppy-builtin-codex",
            Some(("codex", "codex-thread-1")),
        );
        let claude_row = archived_resume_row(
            "p",
            "deppy-builtin-claude",
            Some(("claude", "codex-thread-1")),
        );

        // codex + 같은 thread가 attach돼 있으면 그 local session id를 돌려준다.
        assert_eq!(
            attached_app_server_conflict(Some(&codex_row), |thread_id| {
                (thread_id == "codex-thread-1").then(|| "local-1".to_owned())
            }),
            Some("local-1".to_owned())
        );

        // provider가 codex가 아니면 App Server가 다루는 대상이 아니므로 절대 충돌하지
        // 않는다(같은 문자열이 우연히 겹쳐도 마찬가지).
        assert_eq!(
            attached_app_server_conflict(Some(&claude_row), |thread_id| {
                (thread_id == "codex-thread-1").then(|| "local-1".to_owned())
            }),
            None
        );

        // 그 thread가 App Server에 attach돼 있지 않으면 충돌 없음 — 평소의(다수) 경로.
        assert_eq!(
            attached_app_server_conflict(Some(&codex_row), |_| None),
            None
        );

        // PTY 바인딩 자체가 없는 pane(row: None)은 판정 대상이 아니다.
        assert_eq!(
            attached_app_server_conflict(None, |_| Some("x".to_owned())),
            None
        );
    }

    #[test]
    fn work_history_projection은_시각만_바뀌면_중복이고_요약은_같은_identity를_갱신한다() {
        let row = storage::AgentWorkTurnUpsert {
            workspace_id: "workspace".to_owned(),
            pane_id: "pane".to_owned(),
            kind: "codex".to_owned(),
            agent_session_id: "native".to_owned(),
            turn_key: "codex:42".to_owned(),
            source_offset: 42,
            instruction: "Implement history".to_owned(),
            agent_summary: Some("Working".to_owned()),
            messages_json: None,
            model: Some("gpt-5.6-sol".to_owned()),
            effort: Some("xhigh".to_owned()),
            cwd: Some("/tmp/project".to_owned()),
            branch: None,
            git_change_count: None,
            state: storage::AgentWorkTurnState::Working,
            occurred_at: Some(1),
            updated_at: 10,
        };
        let mut later_poll = row.clone();
        later_poll.updated_at = 20;
        assert!(same_work_history_projection(&row, &later_poll));
        assert_eq!(work_history_key(&row), work_history_key(&later_poll));

        later_poll.agent_summary = Some("Completed".to_owned());
        later_poll.state = storage::AgentWorkTurnState::Completed;
        assert!(!same_work_history_projection(&row, &later_poll));

        let mut duplicate_prompt = row.clone();
        duplicate_prompt.turn_key = "codex:84".to_owned();
        duplicate_prompt.source_offset = 84;
        assert_ne!(work_history_key(&row), work_history_key(&duplicate_prompt));
    }

    #[test]
    fn work_history_cwd는_newest_첫관측에만_캡처되고_duplicate_poll에서_보존된다() {
        let first = detected_work_history_facts(None, Some("/repo/first"));
        assert_eq!(first, (Some("/repo/first".to_owned()), None, None));

        let acknowledged = (
            Some("/repo/first".to_owned()),
            Some("main".to_owned()),
            Some(3),
        );
        let duplicate =
            detected_work_history_facts(Some(acknowledged.clone()), Some("/repo/moved"));
        assert_eq!(duplicate, acknowledged);

        let durable = (
            Some("/repo/durable".to_owned()),
            Some("feature/history".to_owned()),
            Some(7),
        );
        let reloaded =
            detected_work_history_facts(Some(durable.clone()), Some("/repo/moved-again"));
        assert_eq!(reloaded, durable);

        let older_first_seen = detected_work_history_facts(None, None);
        assert_eq!(older_first_seen, (None, None, None));
    }

